$logfile = 'C:\Windows\Setup\Scripts\RemoveEdge.log';
& {
	reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\EdgeUpdate" /v "Install{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}" /t REG_DWORD /d 0 /f;

	$paths = @(
		"${env:ProgramFiles}\Microsoft\Edge\Application";
		"${env:ProgramFiles(x86)}\Microsoft\Edge\Application";
	) | Where-Object -FilterScript { Test-Path -LiteralPath $_ };
	$setup = Get-ChildItem -Path $paths -Filter 'setup.exe' -Recurse -ErrorAction 'SilentlyContinue' |
		Where-Object -FilterScript { $_.Directory.Name -eq 'Installer' } |
		Sort-Object -Property { [version] $_.Directory.Parent.Name } -Descending |
		Select-Object -First 1;
	if( $setup ) {
		Start-Process -FilePath $setup.FullName -ArgumentList '--uninstall', '--system-level', '--verbose-logging', '--force-uninstall' -Wait -ErrorAction 'Continue';
		'Edge removal attempted via {0}.' -f $setup.FullName;
	} else {
		'Edge installer (setup.exe) not found; nothing to remove.';
	}

	reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\EdgeUpdate" /v "Update{56EB18F8-B008-4CBD-B6D2-8C97FE7E9062}" /t REG_DWORD /d 0 /f;
} *>&1 | Out-String -Width 1KB -Stream >> $logfile;

function Test-ChromeInstalled {
	(Test-Path -LiteralPath "${env:ProgramFiles}\Google\Chrome\Application\chrome.exe") -or
	(Test-Path -LiteralPath "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe");
}

function Wait-Network {
	for( $i = 0; $i -lt 36; $i++ ) {
		try {
			if( [System.Net.Dns]::GetHostAddresses( 'dl.google.com' ) ) {
				return $true;
			}
		} catch {}
		Start-Sleep -Seconds 5;
	}
	return $false;
}

if( -not ( Test-ChromeInstalled ) ) {
	if( -not ( Wait-Network ) ) {
		'Sem rede apos 3 minutos; Chrome nao foi instalado.';
		return;
	}
	try {
		$uri = [uri]::new( 'https://dl.google.com/chrome/install/chrome_installer.exe' );
		$arquivo = "$env:TEMP\{0}" -f $uri.Segments[-1];
		[System.Net.WebClient]::new().DownloadFile( $uri, $arquivo );
		Start-Process -FilePath $arquivo -ArgumentList '/silent /install --system-level' -Wait;
		Remove-Item -LiteralPath $arquivo -ErrorAction 'SilentlyContinue';
	} catch {
		$_;
	}
}

